## Funciones de orden superior

Una **función de orden superior** (Higher-Order Function, HOF) es una función que:
- **Recibe** otra función como argumento, o
- **Retorna** una función como resultado (o ambas cosas)

Ya las usaste en el básico: `map`, `filter` y `reduce` son funciones de orden superior. Ahora vamos a entender el concepto y crear las nuestras.

---

## ¿Por qué existen?

Permiten **abstraer comportamiento** — separar el "qué hacer" del "cómo hacerlo":

```javascript
// Sin HOF: código repetido
const numeros = [1, 2, 3, 4, 5];

const dobles = [];
for (const n of numeros) {
  dobles.push(n * 2);
}

const triples = [];
for (const n of numeros) {
  triples.push(n * 3);
}

// Con HOF: comportamiento abstraído
const transformar = (arr, fn) => arr.map(fn);

const dobles2 = transformar(numeros, n => n * 2);
const triples2 = transformar(numeros, n => n * 3);
```

---

## Recibir funciones como argumento

```javascript
function ejecutarDosVeces(fn) {
  fn();
  fn();
}

ejecutarDosVeces(() => console.log('Hola')); // Hola\nHola

// Más útil:
function aplicarATodos(array, transformacion) {
  const resultado = [];
  for (const item of array) {
    resultado.push(transformacion(item));
  }
  return resultado;
}

const precios = [100, 250, 80, 320];
const conIva = aplicarATodos(precios, p => p * 1.19);
console.log(conIva); // [119, 297.5, 95.2, 380.8]
```

---

## Retornar funciones

```javascript
// Crea comparadores dinámicamente
function crearComparador(propiedad) {
  return (a, b) => {
    if (a[propiedad] < b[propiedad]) return -1;
    if (a[propiedad] > b[propiedad]) return 1;
    return 0;
  };
}

const personas = [
  { nombre: 'Carlos', edad: 30 },
  { nombre: 'Ana', edad: 25 },
  { nombre: 'Luis', edad: 35 },
];

const porEdad = crearComparador('edad');
const porNombre = crearComparador('nombre');

console.log(personas.sort(porEdad).map(p => p.nombre));
// ['Ana', 'Carlos', 'Luis']

console.log(personas.sort(porNombre).map(p => p.nombre));
// ['Ana', 'Carlos', 'Luis']
```

---

## Composición básica

```javascript
// pipe: aplica funciones de izquierda a derecha
function pipe(...fns) {
  return (valor) => fns.reduce((acc, fn) => fn(acc), valor);
}

const procesar = pipe(
  x => x * 2,       // 10 * 2 = 20
  x => x + 5,       // 20 + 5 = 25
  x => x.toString() // '25'
);

console.log(procesar(10)); // '25'
```

---

## HOFs estándar que ya conoces

```javascript
const productos = [
  { nombre: 'Libro', precio: 25000, stock: true },
  { nombre: 'Curso', precio: 50000, stock: false },
  { nombre: 'Plugin', precio: 15000, stock: true },
];

// filter: HOF que recibe predicado
const disponibles = productos.filter(p => p.stock);

// map: HOF que recibe transformador
const nombres = productos.map(p => p.nombre);

// reduce: HOF que recibe acumulador
const total = productos.reduce((sum, p) => sum + p.precio, 0);

// Encadenamiento
const totalDisponible = productos
  .filter(p => p.stock)
  .reduce((sum, p) => sum + p.precio, 0);
// 40000
```

examples.code:
// HOF para reintentar una operación
function conReintentos(fn, maxIntentos) {
  return function (...args) {
    let intentos = 0;
    while (intentos < maxIntentos) {
      try {
        return fn(...args);
      } catch (e) {
        intentos++;
        if (intentos === maxIntentos) throw e;
        console.log(`Intento ${intentos} fallido, reintentando...`);
      }
    }
  };
}

let contador = 0;
const operacionInestable = () => {
  contador++;
  if (contador < 3) throw new Error('Fallo temporal');
  return 'Éxito!';
};

const operacionSegura = conReintentos(operacionInestable, 3);
console.log(operacionSegura()); // 'Éxito!' (tras 2 reintentos)

// HOF para medir rendimiento
function medirTiempo(fn, nombre) {
  return function (...args) {
    const inicio = Date.now();
    const resultado = fn(...args);
    const fin = Date.now();
    console.log(`${nombre} tardó ${fin - inicio}ms`);
    return resultado;
  };
}

const buscarLento = (arr, target) => {
  // Simulación de búsqueda lenta
  return arr.find(x => x === target);
};

const buscarConMetrica = medirTiempo(buscarLento, 'buscarLento');
const datos = Array.from({ length: 1000 }, (_, i) => i);
buscarConMetrica(datos, 999);
// 'buscarLento tardó Xms'

